"""Solutions for half-open integer interval problems.

An interval is a pair ``(start, end)`` meaning the half-open range
``[start, end)``. Pairs with ``start >= end`` are empty and ignored.
All functions return lists of ``(start, end)`` tuples sorted by start.
"""


def _normalized(intervals):
    """Yield sorted (start, end) tuples for non-empty intervals."""
    cleaned = [(int(s), int(e)) for s, e in intervals if s < e]
    cleaned.sort()
    return cleaned


def merge(intervals):
    """Merge overlapping and touching intervals into disjoint blocks."""
    merged = []
    for start, end in _normalized(intervals):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


def free_gaps(intervals, window):
    """Return maximal sub-ranges of window not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    gaps = []
    cursor = ws
    for start, end in merge(intervals):
        start = max(start, ws)
        end = min(end, we)
        if start >= end:
            continue
        if start > cursor:
            gaps.append((cursor, start))
        cursor = max(cursor, end)
        if cursor >= we:
            break
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    """Largest number of intervals covering one common point."""
    events = []
    for start, end in intervals:
        if start < end:
            events.append((start, 1))
            events.append((end, -1))
    # Sort by coordinate; -1 (interval end) before +1 (interval start)
    # so that touching intervals do not count as overlapping.
    events.sort()
    depth = 0
    best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live (see README.md)."""

import time
from collections import OrderedDict


class TTLCache:
    """A bounded LRU cache where each entry may have its own TTL.

    Entries are stored in an ``OrderedDict`` ordered least-recently-used
    first.  Each value is kept as a ``(value, expires_at)`` pair where
    ``expires_at`` is ``None`` for entries that never expire.  An entry
    stored at time ``t`` with lifetime ``ttl`` is considered expired once
    ``clock() >= t + ttl``.
    """

    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if not callable(clock):
            raise TypeError("clock must be callable")
        self._capacity = capacity
        self._clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at); LRU first

    # -- internal helpers -------------------------------------------------

    def _expired(self, entry, now=None):
        """Return True if the ``(value, expires_at)`` entry is expired."""
        expires_at = entry[1]
        if expires_at is None:
            return False
        if now is None:
            now = self._clock()
        return now >= expires_at

    # -- cache operations --------------------------------------------------

    def put(self, key, value, ttl=None):
        """Store ``value`` under ``key``.

        ``ttl`` is the entry lifetime in seconds; ``None`` means the entry
        never expires and a ``ttl <= 0`` raises ``ValueError``.  Re-storing
        an existing (live) key replaces its value, restarts its lifetime and
        makes it the most recently used entry.  Inserting a *new* key into a
        full cache first drops every expired entry; if the cache is still
        full afterwards, the least recently used entry is evicted.
        """
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be a positive number of seconds or None")

        now = self._clock()
        entry = self._data.get(key)
        if entry is not None and self._expired(entry, now):
            # An expired entry counts as absent: drop it, then behave as if
            # the key were brand new.
            del self._data[key]
            entry = None

        if entry is None:
            if len(self._data) >= self._capacity:
                self.evict_expired()
                while len(self._data) >= self._capacity:
                    self._data.popitem(last=False)
        else:
            # Live key: re-insert to move it to the most-recently-used end.
            del self._data[key]

        self._data[key] = (value, None if ttl is None else now + ttl)

    def get(self, key, default=None):
        """Return the live value for ``key`` (which may itself be ``None``).

        A missing or expired key returns ``default``; an expired entry is
        removed.  A live entry becomes the most recently used one.
        """
        entry = self._data.get(key)
        if entry is None:
            return default
        if self._expired(entry):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return entry[0]

    def __contains__(self, key):
        """Return True for a live entry without changing recency."""
        entry = self._data.get(key)
        if entry is None:
            return False
        if self._expired(entry):
            del self._data[key]
            return False
        return True

    def __len__(self):
        """Return the number of live (non-expired) entries."""
        self.evict_expired()
        return len(self._data)

    def keys(self):
        """Return the live keys ordered least recently used first."""
        self.evict_expired()
        return list(self._data.keys())

    def evict_expired(self):
        """Remove all expired entries and return how many were removed."""
        now = self._clock()
        expired = [
            key
            for key, entry in self._data.items()
            if self._expired(entry, now)
        ]
        for key in expired:
            del self._data[key]
        return len(expired)

"""Arithmetic expression evaluator.

Implements a small tokenizer plus a recursive-descent parser for the grammar
described in README.md.  No use of eval/exec/compile/ast.
"""

_FUNCTIONS = ("min", "max", "abs")
_DIGITS = "0123456789"
_SINGLE_CHAR_OPS = "+-*/%(),"


def _is_digit(ch):
    return ch in _DIGITS


def _is_name_start(ch):
    return ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ch == "_"


def _is_name_char(ch):
    return _is_name_start(ch) or _is_digit(ch)


def _tokenize(text):
    """Turn the input string into a list of (kind, value) tokens.

    Kinds: "number" (int/float payload), "name" (function name),
    "op" (operator or punctuation), "end" (sentinel).
    """
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if _is_digit(ch):
            j = i
            while j < n and _is_digit(text[j]):
                j += 1
            is_float = False
            if j < n and text[j] == "." and j + 1 < n and _is_digit(text[j + 1]):
                is_float = True
                j += 1
                while j < n and _is_digit(text[j]):
                    j += 1
            raw = text[i:j]
            tokens.append(("number", float(raw) if is_float else int(raw)))
            i = j
            continue
        if ch == ".":
            if i + 1 < n and _is_digit(text[i + 1]):
                j = i + 1
                while j < n and _is_digit(text[j]):
                    j += 1
                tokens.append(("number", float(text[i:j])))
                i = j
                continue
            raise ValueError("unexpected '.' at position %d" % i)
        if _is_name_start(ch):
            j = i
            while j < n and _is_name_char(text[j]):
                j += 1
            name = text[i:j]
            if name not in _FUNCTIONS:
                raise ValueError("unknown name %r" % name)
            tokens.append(("name", name))
            i = j
            continue
        if text.startswith("**", i):
            tokens.append(("op", "**"))
            i += 2
            continue
        if text.startswith("//", i):
            tokens.append(("op", "//"))
            i += 2
            continue
        if ch in _SINGLE_CHAR_OPS:
            tokens.append(("op", ch))
            i += 1
            continue
        raise ValueError("unexpected character %r at position %d" % (ch, i))
    tokens.append(("end", None))
    return tokens


class _Parser:
    """Recursive-descent parser; precedence from lowest to highest:

    additive (+ -)  <  multiplicative (* / // %)  <  unary (+ -)  <  power (**)
    """

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def match_op(self, *ops):
        kind, value = self.peek()
        if kind == "op" and value in ops:
            self.pos += 1
            return value
        return None

    def expect_op(self, op):
        if not self.match_op(op):
            kind, value = self.peek()
            raise ValueError("expected %r, found %r" % (op, value))

    # ---- grammar levels -------------------------------------------------

    def parse_expression(self):
        return self.parse_additive()

    def parse_additive(self):
        value = self.parse_multiplicative()
        while True:
            op = self.match_op("+", "-")
            if op is None:
                return value
            rhs = self.parse_multiplicative()
            value = value + rhs if op == "+" else value - rhs

    def parse_multiplicative(self):
        value = self.parse_unary()
        while True:
            op = self.match_op("*", "/", "//", "%")
            if op is None:
                return value
            rhs = self.parse_unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = value / rhs  # always float; ZeroDivisionError on 0
            elif op == "//":
                value = value // rhs
            else:
                value = value % rhs

    def parse_unary(self):
        op = self.match_op("+", "-")
        if op is not None:
            operand = self.parse_unary()
            return operand if op == "+" else -operand
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        if self.match_op("**"):
            # Right-associative; the exponent may itself carry unary operators
            # (e.g. `2 ** -3`).  Because unary descent goes through
            # parse_power, `**` binds tighter than a prefix sign, so
            # `-2 ** 2` parses as `-(2 ** 2)`.
            exponent = self.parse_unary()
            return base ** exponent
        return base

    def parse_primary(self):
        kind, value = self.peek()
        if kind == "number":
            self.advance()
            return value
        if kind == "op" and value == "(":
            self.advance()
            result = self.parse_expression()
            self.expect_op(")")
            return result
        if kind == "name":
            self.advance()
            return self.parse_call(value)
        raise ValueError("expected a number, function call, or '('")

    def parse_call(self, name):
        self.expect_op("(")
        if self.match_op(")"):
            raise ValueError("%s() requires at least 1 argument" % name)
        args = [self.parse_expression()]
        while self.match_op(","):
            args.append(self.parse_expression())
        self.expect_op(")")
        if name == "abs":
            if len(args) != 1:
                raise ValueError("abs() takes exactly 1 argument")
            return abs(args[0])
        return min(args) if name == "min" else max(args)

    # ---- top level -------------------------------------------------------

    def parse_program(self):
        result = self.parse_expression()
        kind, value = self.peek()
        if kind != "end":
            raise ValueError("unexpected trailing token %r" % (value,))
        return result


def evaluate(text: str):
    """Parse and evaluate an arithmetic expression string."""
    if not isinstance(text, str):
        raise ValueError("expected a string")
    parser = _Parser(_tokenize(text))
    return parser.parse_program()
